def has_two_sum_sorted(nums: list[int], target: int) -> bool:
    n = len(nums)
    if n < 2:
        return False
    left = 0
    right = n - 1
    while left < right:
        s = nums[left] + nums[right]
        if s == target:
            return True
        elif s < target:
            left += 1
        else:
            right -= 1
    return False

def is_anagram(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    count = {}
    for ch in s:
        if ch in count:
            count[ch] += 1
        else:
            count[ch] = 1
    for ch in t:
        if ch not in count or count[ch] == 0:
            return False
        count[ch] -= 1
    for v in count.values():
        if v != 0:
            return False
    return True

def range_sums(nums: list[int], queries: list[tuple[int, int]]) -> list[int]:
    n = len(nums)
    if n == 0 or len(queries) == 0:
        return []
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i+1] = pref[i] + nums[i]
    res = []
    for l, r in queries:
        res.append(pref[r+1] - pref[l])
    return res

def normalize_spaces(text: str) -> str:
    words = []
    current = []
    for ch in text:
        if ch == ' ' or ch == '\t' or ch == '\n':
            if current:
                words.append(''.join(current))
                current = []
        else:
            current.append(ch)
    if current:
        words.append(''.join(current))
    return ' '.join(words)

def atm_balance(ops):
    balance = 0
    for op in ops:
        if op > 0:
            balance += op
        elif op < 0:
            if -op <= balance:
                balance += op
    return balance

def is_balanced(s: str) -> bool:
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in mapping.values():
            stack.append(c)
        else:
            if not stack or stack.pop() != mapping[c]:
                return False
    return len(stack) == 0

def trailing_zeros(n: int) -> int:
