def reverse_vowels(s: str) -> str:
    vowels = set('aeiouAEIOU')
    lst = list(s)
    l, r = 0, len(lst) - 1
    while l < r:
        while l < r and lst[l] not in vowels:
            l += 1
        while l < r and lst[r] not in vowels:
            r -= 1
        if l < r:
            lst[l], lst[r] = lst[r], lst[l]
            l += 1
            r -= 1
    return ''.join(lst)

def is_symmetric(matrix):
