    if n == 0:
        return True
    for row in matrix:
        if len(row) != n:
            return False
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

def count_positive_multiples(nums: list[int], k: int) -> int:
