def sort_by_frequency(nums):
    if len(nums) == 0:
        return []
    freq = {}
    for x in nums:
        if x in freq:
            freq[x] += 1
        else:
            freq[x] = 1
    keys = list(freq.keys())
    def get_key(x):
        return (-freq[x], x)
    return sorted(keys, key=get_key)

def length_of_longest_substring(s: str) -> int:
    last = {}
    max_len = 0
    left = 0
    for right, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = right
        curr_len = right - left + 1
        if curr_len > max_len:
            max_len = curr_len
    return max_len

def first_ge(nums: list[int], target: int) -> int:
    lo = 0
    hi = len(nums)
    while lo < hi:
        mid = divmod(lo + hi, 2)[0]
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(nums):
