def count_pairs_in_range(nums, low, high):
    freq = {}
    for x in nums:
        if x in freq:
            freq[x] += 1
        else:
            freq[x] = 1
    vals = sorted(freq.keys())
    k = len(vals)
    ans = 0
    for i in range(k):
        vi = vals[i]
        fi = freq[vi]
        for j in range(i, k):
            vj = vals[j]
            s = vi + vj
            if low <= s <= high:
                if i == j:
                    ans += fi * (fi - 1) // 2
                else:
                    ans += fi * freq[vj]
    return ans

