def max_area(heights: list[int]) -> int:
    if len(heights) < 2:
        return 0
    l = 0
    r = len(heights) - 1
    max_a = 0
    while l < r:
        w = r - l
        h = min(heights[l], heights[r])
        a = w * h
        if a > max_a:
            max_a = a
        if heights[l] <= heights[r]:
            l += 1
        else:
            r -= 1
    return max_a

