def daily_warmer(temps):
    n = len(temps)
    ans = [0] * n
    stack = []
    for i in range(n):
        while stack and temps[i] > temps[stack[-1]]:
            idx = stack.pop()
            ans[idx] = i - idx
        stack.append(i)
    return ans

def fast_power(x: float, n: int) -> float:
    if n == 0:
        return 1.0
    if n < 0:
        return 1.0 / fast_power(x, -n)
    half = fast_power(x, n // 2)
    if n % 2 == 0:
        return half * half
    else:
        return x * half * half

def spiral_order(matrix):
    if not matrix or not matrix[0]:
        return []
    res = []
    top = 0
    bottom = len(matrix) - 1
    left = 0
    right = len(matrix[0]) - 1
    while top <= bottom and left <= right:
        for i in range(left, right + 1):
            res.append(matrix[top][i])
        for i in range(top + 1, bottom + 1):
            res.append(matrix[i][right])
        if top < bottom:
            for i in range(right - 1, left - 1, -1):
                res.append(matrix[bottom][i])
        if left < right:
            for i in range(bottom - 1, top, -1):
                res.append(matrix[i][left])
        top += 1
        bottom -= 1
        left += 1
        right -= 1
    return res

def jump_count(nums: list[int]) -> int:
    n = len(nums)
    if n <= 1:
        return 0
    jumps = 0
    cur_end = 0
    farthest = 0
    for i in range(n - 1):
        farthest = max(farthest, i + nums[i])
        if i == cur_end:
            jumps += 1
            cur_end = farthest
            if cur_end >= n - 1:
                break
    return jumps

def top_scores(scores: list[int], k: int) -> list[int]:
    if k == 0 or len(scores) == 0:
        return []
    cnt = {}
    for s in scores:
        if s in cnt:
            cnt[s] += 1
        else:
            cnt[s] = 1
    items = [(cnt[s], s) for s in cnt]
    items = sorted(items, reverse=True)
    res = []
    for i in range(k if k < len(items) else len(items)):
        res.append(items[i][1])
    return res

def str_str(haystack: str, needle: str) -> int:
    if not needle:
        return 0
    n = len(needle)
    lps = [0] * n
    length = 0
    i = 1
    while i < n:
        if needle[i] == needle[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length != 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    m = len(haystack)
    i = 0
    j = 0
    while i < m:
        if haystack[i] == needle[j]:
            i += 1
            j += 1
            if j == n:
                return i - j
        elif j != 0:
            j = lps[j - 1]
        else:
            i += 1
    return -1

def max_sliding(nums: list[int], k: int) -> list[int]:
    if not nums or k <= 0 or k > len(nums):
        return []
    q = []
    head = 0
    res = []
    for i, x in enumerate(nums):
        if q and q[head] <= i - k:
            head += 1
        while q and nums[q[-1]] <= x:
            q.pop()
            if not q:
                head = 0
        q.append(i)
        if i >= k - 1:
            res.append(nums[q[head]])
    return res

def search_rotated(nums: list[int], target: int) -> int:
    n = len(nums)
    if n == 0:
        return -1
    left = 0
    right = n - 1
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            return mid
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

def merge_sorted(a, b):
    i = 0
    j = 0
    res = []
    n = len(a)
    m = len(b)
    while i < n and j < m:
        if a[i] <= b[j]:
            res.append(a[i])
            i += 1
        else:
            res.append(b[j])
            j += 1
    while i < n:
        res.append(a[i])
        i += 1
    while j < m:
        res.append(b[j])
        j += 1
    return res

def kth_largest(nums: list[int], k: int) -> int:
    a = list(nums)
    n = len(a)
    lo = 0
    hi = n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        x = a[lo]; y = a[mid]; z = a[hi]
        if x <= y <= z or z <= y <= x:
            pivot = y
        elif y <= x <= z or z <= x <= y:
            pivot = x
        else:
            pivot = z
        lt = lo
        gt = hi
        i = lo
        while i <= gt:
            if a[i] > pivot:
                a[lt], a[i] = a[i], a[lt]
                lt += 1
                i += 1
            elif a[i] < pivot:
                a[i], a[gt] = a[gt], a[i]
                gt -= 1
            else:
                i += 1
        count_gt = lt - lo
        count_eq = gt - lt + 1
        if k <= count_gt:
            hi = lt - 1
        elif k <= count_gt + count_eq:
            return pivot
        else:
            k = k - count_gt - count_eq
            lo = gt + 1
    return a[lo]

def intersect_sorted(a: list[int], b: list[int]) -> list[int]:
    i = 0
    j = 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            res.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return res

def group_anagrams(words: list[str]) -> list[list[str]]:
    groups = {}
    order = []
    for w in words:
        key = tuple(sorted(w.lower()))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(w)
    result = []
    for k in order:
        result.append(groups[k])
    return result

def is_valid_stack_sequence(pushed, popped):
    if len(pushed) != len(popped):
        return False
    stack = []
    j = 0
    for x in pushed:
        stack.append(x)
        while stack and j < len(popped) and stack[-1] == popped[j]:
            stack.pop()
            j += 1
    return len(stack) == 0

def min_cover_count(intervals, s, t):
    if s >= t:
        return 0
    intervals = sorted(intervals, key=lambda x: x[0])
    cur = s
    count = 0
    i = 0
    n = len(intervals)
    while cur < t:
        max_r = cur
        while i < n and intervals[i][0] <= cur:
            if intervals[i][1] > max_r:
                max_r = intervals[i][1]
            i += 1
        if max_r == cur:
            return -1
        cur = max_r
        count += 1
    return count

def min_palindrome_inserts(s: str) -> int:
    n = len(s)
    if n <= 1:
        return 0
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 0
                else:
                    dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = min(dp[i+1][j], dp[i][j-1]) + 1
    return dp[0][n-1]

def three_sum_zero(nums):
    if len(nums) < 3:
        return []
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    res = []
    for i in range(n - 2):
        if i > 0 and nums_sorted[i] == nums_sorted[i - 1]:
            continue
        target = -nums_sorted[i]
        left = i + 1
        right = n - 1
        while left < right:
            s = nums_sorted[left] + nums_sorted[right]
            if s == target:
                res.append([nums_sorted[i], nums_sorted[left], nums_sorted[right]])
                while left < right and nums_sorted[left] == nums_sorted[left + 1]:
                    left += 1
                while left < right and nums_sorted[right] == nums_sorted[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif s < target:
                left += 1
            else:
                right -= 1
    return res

def cycle_info(nexts: list[int]) -> list[int]:
    n = len(nexts)
    if n == 0:
        return [-1, 0]
    slow = 0
    fast = 0
    while True:
        if nexts[slow] == -1:
            return [-1, 0]
        slow = nexts[slow]
        if nexts[fast] == -1:
            return [-1, 0]
        fast = nexts[fast]
        if nexts[fast] == -1:
            return [-1, 0]
        fast = nexts[fast]
        if slow == fast:
            break
    entry = 0
    while entry != slow:
        entry = nexts[entry]
        slow = nexts[slow]
    length = 1
    cur = nexts[entry]
    while cur != entry:
        cur = nexts[cur]
        length += 1
    return [entry, length]

def count_digit_range(lo, hi, d):
    def count_up_to(n):
        if n < 0:
            return 0
        ans = 1 if d == 0 else 0
        factor = 1
        while factor <= n:
            higher = n // (factor * 10)
            current = (n // factor) % 10
            lower = n % factor
            if d != 0:
                ans += higher * factor
                if current > d:
                    ans += factor
                elif current == d:
                    ans += lower + 1
            else:
                if higher > 0:
                    ans += (higher - 1) * factor
                    if current > 0:
                        ans += factor
                    elif current == 0:
                        ans += lower + 1
            factor *= 10
        return ans
    return count_up_to(hi) - count_up_to(lo - 1)

def max_overlap(events):
    pts = []
    for ev in events:
        s = ev[0]
        e = ev[1]
        if s < e:
            pts.append((s, 1))
            pts.append((e, -1))
    pts = sorted(pts)
    cur = 0
    best = 0
    for coord, d in pts:
        cur += d
        if cur > best:
            best = cur
    return best

def zigzag_levels(children: list[list[int]]) -> list[list[int]]:
    if not children:
        return []
    result = []
    current = [0]
    level = 0
    while current:
        if level % 2 == 1:
            out = list(reversed(current))
        else:
            out = current[:]
        result.append(out)
        nxt = []
        for node in current:
            for child in children[node]:
                nxt.append(child)
        current = nxt
        level += 1
    return result

def lcs_lex_smallest(a: str, b: str) -> str:
    n = len(a)
    m = len(b)
    f = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                f[i][j] = 1 + f[i + 1][j + 1]
            else:
                f[i][j] = max(f[i + 1][j], f[i][j + 1])
    memo = {}
    letters = "abcdefghijklmnopqrstuvwxyz"
    def get(i, j):
        if f[i][j] == 0:
            return ""
        if (i, j) in memo:
            return memo[(i, j)]
        target = f[i][j] - 1
        best = None
        for c in letters:
            for x in range(i, n):
                if a[x] != c:
                    continue
                for y in range(j, m):
                    if b[y] != c:
                        continue
                    if f[x + 1][y + 1] == target:
                        cand = c + get(x + 1, y + 1)
                        if best is None or cand < best:
                            best = cand
            if best is not None:
                break
        memo[(i, j)] = best
        return best
    return get(0, 0)

def min_merge_cost(stones):
    n = len(stones)
    if n <= 1:
        return 0
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i+1] = pref[i] + stones[i]
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i, j):
                cost = dp[i][k] + dp[k+1][j] + (pref[j+1] - pref[i])
                if cost < dp[i][j]:
                    dp[i][j] = cost
    return dp[0][n-1]

def min_cover_circular_len(s: str, t: str) -> int:
    if len(t) == 0:
        return 0
    n = len(s)
    if n == 0 or len(t) > n:
        return -1
    need = {}
    for ch in t:
        if ch in need:
            need[ch] += 1
        else:
            need[ch] = 1
    double = s + s
    m = len(double)
    window = {}
    left = 0
    need_cnt = len(t)
    min_len = n + 1
    for right in range(m):
        ch = double[right]
        if ch in window:
            window[ch] += 1
        else:
            window[ch] = 1
        if ch in need and window[ch] <= need[ch]:
            need_cnt -= 1
        while right - left + 1 > n:
            left_ch = double[left]
            if left_ch in need and window[left_ch] <= need[left_ch]:
                need_cnt += 1
            window[left_ch] -= 1
            left += 1
        while need_cnt == 0:
            cur_len = right - left + 1
            if cur_len < min_len:
                min_len = cur_len
            left_ch = double[left]
            if left_ch in need and window[left_ch] <= need[left_ch]:
                need_cnt += 1
            window[left_ch] -= 1
            left += 1
    if min_len <= n:
        return min_len
    else:
        return -1

def longest_k_palindrome(s: str, k: int) -> int:
    n = len(s)
    if n == 0:
        return 0
    max_len = 0
    for i in range(n):
        left = i
        right = i
        mismatch = 0
        while left >= 0 and right < n:
            if s[left] != s[right]:
                mismatch += 1
            if mismatch > k:
                break
            cur = right - left + 1
            if cur > max_len:
                max_len = cur
            left -= 1
            right += 1
    for i in range(n - 1):
        left = i
        right = i + 1
        mismatch = 0
        while left >= 0 and right < n:
            if s[left] != s[right]:
                mismatch += 1
            if mismatch > k:
                break
            cur = right - left + 1
            if cur > max_len:
                max_len = cur
            left -= 1
            right += 1
    return max_len

def top_k_frequent(nums, k):
    if k <= 0 or len(nums) == 0:
        return []
    freq = {}
    for x in nums:
        if x in freq:
            freq[x] += 1
        else:
            freq[x] = 1
    heap = []
    def sift_up(i):
        while i > 0:
            p = (i - 1) // 2
            if heap[i] < heap[p]:
                heap[i], heap[p] = heap[p], heap[i]
                i = p
            else:
                break
    def sift_down(i):
        n = len(heap)
        while True:
            l = 2 * i + 1
            r = 2 * i + 2
            smallest = i
            if l < n and heap[l] < heap[smallest]:
                smallest = l
            if r < n and heap[r] < heap[smallest]:
                smallest = r
            if smallest != i:
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
            else:
                break
    def push(item):
        heap.append(item)
        sift_up(len(heap) - 1)
    def pop():
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            sift_down(0)
        return top
    for num, f in freq.items():
        push((-f, num))
    res = []
    limit = min(k, len(heap))
    for _ in range(limit):
        negf, num = pop()
        res.append(num)
    return res

def knapsack_exact(weights, values, cap):
    dp = [-1] * (cap + 1)
    dp[0] = 0
    n = len(weights)
    for i in range(n):
        w = weights[i]
        v = values[i]
        for j in range(cap, w - 1, -1):
            if dp[j - w] != -1:
                if dp[j] < dp[j - w] + v:
                    dp[j] = dp[j - w] + v
    return dp[cap]

def min_spanning_cost(n: int, edges: list[list[int]]) -> int:
    if n <= 1:
        return 0
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx != ry:
            parent[rx] = ry
            return True
        return False
    def weight(e):
        return e[2]
    sorted_edges = sorted(edges, key=weight)
    total = 0
    count = 0
    for e in sorted_edges:
        u, v, w = e[0], e[1], e[2]
        if u == v:
            continue
        if union(u, v):
            total += w
            count += 1
            if count == n - 1:
                break
    if count == n - 1:
        return total
    else:
        return -1

def min_max_split_sum(nums: list[int], k: int) -> int:
    if not nums:
        return 0
    left = max(nums)
    right = sum(nums)
    while left < right:
        mid = (left + right) // 2
        cnt = 1
        cur = 0
        possible = True
        for x in nums:
            if cur + x <= mid:
                cur += x
            else:
                cnt += 1
                cur = x
                if cur > mid:
                    possible = False
                    break
        if possible and cnt <= k:
            right = mid
        else:
            left = mid + 1
    return left

def count_submatrices_sum_eq(matrix, target):
    if not matrix or not matrix[0]:
        return 0
    n = len(matrix)
    m = len(matrix[0])
    ans = 0
    for r1 in range(n):
        col_sum = [0] * m
        for r2 in range(r1, n):
            for c in range(m):
                col_sum[c] += matrix[r2][c]
            pref_counts = dict()
            pref_counts[0] = 1
            prefix = 0
            for c in range(m):
                prefix += col_sum[c]
                need = prefix - target
                if need in pref_counts:
                    ans += pref_counts[need]
                if prefix in pref_counts:
                    pref_counts[prefix] += 1
                else:
                    pref_counts[prefix] = 1
    return ans

def lex_topo_order(n: int, edges: list[list[int]]) -> list[int]:
    indeg = [0] * n
    adj = []
    for i in range(n):
        adj.append([])
    for e in edges:
        u = e[0]
        v = e[1]
        adj[u].append(v)
        indeg[v] += 1
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heap.append(i)
            ci = len(heap) - 1
            while ci > 0:
                p = (ci - 1) // 2
                if heap[p] > heap[ci]:
                    heap[p], heap[ci] = heap[ci], heap[p]
                    ci = p
                else:
                    break
    res = []
    while heap:
        x = heap[0]
        heap[0] = heap[-1]
        heap.pop()
        if heap:
            i = 0
            m = len(heap)
            while True:
                l = 2 * i + 1
                r = 2 * i + 2
                sm = i
                if l < m and heap[l] < heap[sm]:
                    sm = l
                if r < m and heap[r] < heap[sm]:
                    sm = r
                if sm != i:
                    heap[i], heap[sm] = heap[sm], heap[i]
                    i = sm
                else:
                    break
        res.append(x)
        for v in adj[x]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heap.append(v)
                ci = len(heap) - 1
                while ci > 0:
                    p = (ci - 1) // 2
                    if heap[p] > heap[ci]:
                        heap[p], heap[ci] = heap[ci], heap[p]
                        ci = p
                    else:
                        break
    if len(res) != n:
        return []
    return res

def count_digit_sum_divisible(n: int, k: int) -> int:
    if n == 0:
        digits = [0]
    else:
        digits = []
        temp = n
        while temp > 0:
            digits.append(temp % 10)
            temp //= 10
        digits = list(reversed(digits))
    dp = [[0] * k for _ in range(2)]
    dp[1][0] = 1
    for digit in digits:
        new_dp = [[0] * k for _ in range(2)]
        for t in range(2):
            for r in range(k):
                cnt = dp[t][r]
                if cnt == 0:
                    continue
                upper = digit if t == 1 else 9
                for d in range(upper + 1):
                    nr = (r + d) % k
                    nt = 1 if (t == 1 and d == upper) else 0
                    new_dp[nt][nr] += cnt
        dp = new_dp
    return dp[0][0] + dp[1][0]

def tree_knapsack(weights: list[int], children: list[list[int]], k: int) -> int:
    n = len(weights)
    if n == 0:
        return 0 if k == 0 else -1
    dp0 = [[-1] * (k + 1) for _ in range(n)]
    dp1 = [[-1] * (k + 1) for _ in range(n)]
    for u in range(n - 1, -1, -1):
        cur0 = [-1] * (k + 1)
        cur1 = [-1] * (k + 1)
        cur0[0] = 0
        if k >= 1:
            cur1[1] = weights[u]
        for v in children[u]:
            new0 = [-1] * (k + 1)
            new1 = [-1] * (k + 1)
            for i in range(k + 1):
                if cur0[i] != -1:
                    for j in range(k - i + 1):
                        val = dp0[v][j] if dp0[v][j] > dp1[v][j] else dp1[v][j]
                        if val != -1:
                            s = i + j
                            total = cur0[i] + val
                            if total > new0[s]:
                                new0[s] = total
                if cur1[i] != -1:
                    for j in range(k - i + 1):
                        if dp0[v][j] != -1:
                            s = i + j
                            total = cur1[i] + dp0[v][j]
                            if total > new1[s]:
                                new1[s] = total
            cur0 = new0
            cur1 = new1
        dp0[u] = cur0
        dp1[u] = cur1
    ans = -1
    if dp0[0][k] > ans:
        ans = dp0[0][k]
    if dp1[0][k] > ans:
        ans = dp1[0][k]
    return ans

def tsp_min_path(dist):
    n = len(dist)
    if n <= 1:
        return 0
    N = 1 << n
    BIG = 10**9
    dp = []
    for mask in range(N):
        row = []
        for i in range(n):
            row.append(BIG)
        dp.append(row)
    dp[1][0] = 0
    for mask in range(N):
        for i in range(n):
            if dp[mask][i] == BIG:
                continue
            if not (mask & (1 << i)):
                continue
            for j in range(n):
                if mask & (1 << j):
                    continue
                new_mask = mask | (1 << j)
                cost = dp[mask][i] + dist[i][j]
                if cost < dp[new_mask][j]:
                    dp[new_mask][j] = cost
    full = (1 << n) - 1
    ans = BIG
    for i in range(n):
        if dp[full][i] < ans:
            ans = dp[full][i]
    return ans

def count_interleavings(s1, s2, s3):
    if len(s1)+len(s2)!=len(s3):
        return 0
    n1=len(s1)
    n2=len(s2)
    dp=[0]*(n2+1)
    dp[0]=1
    for j in range(1,n2+1):
        dp[j]=dp[j-1] if s2[j-1]==s3[j-1] else 0
    for i in range(1,n1+1):
        dp[0]=dp[0] if s1[i-1]==s3[i-1] else 0
        for j in range(1,n2+1):
            from1 = dp[j] if s1[i-1]==s3[i+j-1] else 0
            from2 = dp[j-1] if s2[j-1]==s3[i+j-1] else 0
            dp[j]=from1+from2
    return dp[n2]

def longest_bitonic_subsequence(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    inc = [0] * n
    dec = [0] * n
    tails = []
    for i in range(n):
        x = nums[i]
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
        inc[i] = lo + 1
    tails = []
    for i in range(n - 1, -1, -1):
        x = nums[i]
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
        dec[i] = lo + 1
    ans = 0
    for i in range(n):
        cur = inc[i] + dec[i] - 1
        if cur > ans:
            ans = cur
    return ans

def knapsack_2d(weights, volumes, values, cap_w, cap_v):
    dp = [[0] * (cap_v + 1) for _ in range(cap_w + 1)]
    n = len(weights)
    for i in range(n):
        w_i = weights[i]
        v_i = volumes[i]
        val = values[i]
        for w in range(cap_w, w_i - 1, -1):
            for v in range(cap_v, v_i - 1, -1):
                dp[w][v] = max(dp[w][v], dp[w - w_i][v - v_i] + val)
    return dp[cap_w][cap_v]

def min_concat_number(nums: list[int]) -> str:
    if len(nums) == 0:
        return ''
    all_zero = True
    for num in nums:
        if num != 0:
            all_zero = False
            break
    if all_zero:
        return '0'
    strs = []
    for num in nums:
        strs.append(str(num))
    size = len(strs)
    for i in range(size):
        for j in range(0, size - i - 1):
            if strs[j] + strs[j+1] > strs[j+1] + strs[j]:
                temp = strs[j]
                strs[j] = strs[j+1]
                strs[j+1] = temp
    result = ''
    for s in strs:
        result += s
    return result

def min_rooms_with_gap(intervals, gap):
    if not intervals:
        return 0
    sorted_intervals = sorted(intervals)
    heap = []
    def push(val):
        heap.append(val)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) // 2
            if heap[p] <= heap[i]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p
    def pop():
        if len(heap) == 1:
            return heap.pop()
        root = heap[0]
        heap[0] = heap.pop()
        i = 0
        n = len(heap)
        while True:
            l = 2 * i + 1
            r = 2 * i + 2
            sm = i
            if l < n and heap[l] < heap[sm]:
                sm = l
            if r < n and heap[r] < heap[sm]:
                sm = r
            if sm == i:
                break
            heap[i], heap[sm] = heap[sm], heap[i]
            i = sm
        return root
    for interval in sorted_intervals:
        start, end = interval[0], interval[1]
        if heap and heap[0] + gap <= start:
            pop()
        push(end)
    return len(heap)

def stone_game_diff(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = nums[i]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            best = nums[i] - dp[i+1][j]
            val = nums[i] + nums[i+1] - (dp[i+2][j] if i+2 <= j else 0)
            if val > best:
                best = val
            val = nums[j] - dp[i][j-1]
            if val > best:
                best = val
            val = nums[j-1] + nums[j] - (dp[i][j-2] if j-2 >= i else 0)
            if val > best:
                best = val
            dp[i][j] = best
    return dp[0][n-1]

def min_spanning_tree_cost(n, edges):
    if n <= 1:
        return 0
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    sorted_edges = sorted(edges, key=lambda e: e[2])
    total = 0
    count = 0
    for e in sorted_edges:
        u, v, w = e[0], e[1], e[2]
        if u == v:
            continue
        if union(u, v):
            total += w
            count += 1
            if count == n - 1:
                break
    return total if count == n - 1 else -1

def shortest_path_cost(n, edges, src, dst):
    if src == dst:
        return 0
    INF = 10**18
    adj = []
    for i in range(n):
        adj.append([])
    for e in edges:
        u = e[0]; v = e[1]; w = e[2]
        adj[u].append((v, w))
    dist = []
    for i in range(n):
        dist.append(INF)
    dist[src] = 0
    heap = []
    def push(item):
        heap.append(item)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) // 2
            if heap[i][0] < heap[p][0]:
                heap[i], heap[p] = heap[p], heap[i]
                i = p
            else:
                break
    def pop():
        if not heap:
            return None
        res = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = 2 * i + 1
                r = 2 * i + 2
                small = i
                if l < len(heap) and heap[l][0] < heap[small][0]:
                    small = l
                if r < len(heap) and heap[r][0] < heap[small][0]:
                    small = r
                if small != i:
                    heap[i], heap[small] = heap[small], heap[i]
                    i = small
                else:
                    break
        return res
    push((0, src))
    while heap:
        item = pop()
        d = item[0]; u = item[1]
        if d > dist[u]:
            continue
        if u == dst:
            return d
        for edge in adj[u]:
            v = edge[0]; w = edge[1]
            if d + w < dist[v]:
                dist[v] = d + w
                push((dist[v], v))
    return -1

def feasible_binary_array(n, constraints):
    V = n + 1
    edges = []
    for c in constraints:
        l, r, lo, hi = c
        edges.append((l, r + 1, lo))
        edges.append((r + 1, l, -hi))
    for i in range(n):
        edges.append((i, i + 1, 0))
        edges.append((i + 1, i, -1))
    dist = [-10**9] * V
    dist[0] = 0
    for _ in range(V - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != -10**9 and dist[u] + w > dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            return True
    for u, v, w in edges:
        if dist[u] != -10**9 and dist[u] + w > dist[v]:
            return False
    return True
